(function(){
'use strict';
const S=SoloEngine, el=()=>document.querySelector('#content');
let s=null,difficulty='normal',locked=false;
function button(label,action,disabled=false,cls=''){return '<button '+(disabled?'disabled ':'')+'class="'+cls+'" onclick="'+action+'">'+label+'</button>'}
function card(c){const color=S.colors.find(x=>x.id===c.color);return '<span class="solo-card" style="--card-color:'+color.hex+'"><small>'+color.name+'</small><strong>'+c.n+'</strong></span>'}
function status(message){return '<p class="message" role="status" aria-live="polite">'+message+'</p>'}
function done(name,score,message,complete,log){window.finish(name,score,message,complete,log)}
window.soloStart=function(id){locked=false;active=true;if(id==='chain'){s=S.freshChain();state={id};chainRender()}else if(id==='line'){difficulty=document.querySelector('#difficulty')?.value||'normal';s={board:Array(25).fill(0),turn:0,history:[]};state={id};lineRender()}}
function chainRender(message='왼쪽 또는 오른쪽 끝에 연결할 카드를 선택하세요.'){if(!s||state?.id!=='chain')return;const moves=S.chainMoves(s),over=S.chainOver(s);if(over){locked=true;const full=s.turn===12;done('숫자 연쇄',s.score,full?'12턴 완료!':'연결 가능한 카드가 없어 종료',full,['배치 '+s.turn+'/12 · 재추첨 '+s.rerolled+'/2','별 '+S.chainStars(s.score)+'개']);return}
const offer=s.offer.map((c,i)=>'<div class="solo-offer">'+card(c)+'<div class="solo-choices">'+button('← 왼쪽','soloPlace('+i+',\'left\')',!moves.some(m=>m.index===i&&m.side==='left'))+button('오른쪽 →','soloPlace('+i+',\'right\')',!moves.some(m=>m.index===i&&m.side==='right'))+'</div></div>').join('');
el().innerHTML='<h2>숫자 연쇄</h2><div class="status"><span>배치 <strong>'+s.turn+'/12</strong></span><span>점수 <strong>'+s.score+'</strong></span><span>재추첨 <strong>'+s.rerolls+'/2</strong></span></div><p class="note">같은 색 또는 숫자 차이가 1인 카드를 연결하세요. 연결 +2점, 숫자 차이 1이면 +1점.</p><div class="solo-chain" aria-label="연결된 카드">'+s.chain.map(card).join('')+'</div><h3>선택 카드</h3><div class="solo-offers">'+offer+'</div>'+button('선택 카드 3장 재추첨','soloReroll()',moves.length>0||s.rerolls===0||s.deck.length===0)+status(message)}
window.soloPlace=function(i,side){if(locked||state?.id!=='chain')return;try{s=S.chainPlace(s,i,side);chainRender('연결 성공!')}catch(e){chainRender(e.message)}};
window.soloReroll=function(){if(locked||state?.id!=='chain')return;try{s=S.chainReroll(s);chainRender('재추첨 완료. 남은 횟수 '+s.rerolls+'회')}catch(e){chainRender(e.message)}};
function lineRender(message='빈칸을 선택해 돌을 놓으세요.'){if(!s||state?.id!=='line')return;const b=s.board,player=S.lineScore(b,1)+S.centerScore(b,1),ai=S.lineScore(b,2)+S.centerScore(b,2);
el().innerHTML='<h2>라인 컨트롤</h2><div class="status"><span>턴 <strong>'+s.turn+'/10</strong></span><span>나 <strong>'+player+'</strong></span><span>AI <strong>'+ai+'</strong></span><span>난이도 <strong>'+({easy:'쉬움',normal:'보통',hard:'어려움'}[difficulty])+'</strong></span></div><p class="note">가로·세로·대각선의 연속 3칸마다 3점. 중앙 3×3에 놓인 돌마다 종료 시 1점 추가.</p><div class="solo-grid" role="group" aria-label="5행 5열 게임판">'+b.map((v,i)=>button(v===1?'●':v===2?'◆':'·','soloMove('+i+')',v!==0||locked,'solo-cell '+(v===1?'solo-player':v===2?'solo-ai':''))).join('')+'</div>'+status(message)+'<p class="note">나: 파란 원 ● / AI: 붉은 마름모 ◆ · 각 10회 착수</p>'}
window.soloMove=function(i){if(locked||state?.id!=='line'||s.board[i]!==0||s.turn>=10)return;locked=true;const before=s.board;s.board=S.lineStep(before,i,1);const gained=S.newLineWindows(before,s.board,1).length;lineRender('나의 착수 완료'+(gained?' · '+gained+'개 라인 완성!':''));const move=S.chooseLineMove(s.board,difficulty);if(move>=0){const prev=s.board;s.board=S.lineStep(prev,move,2);s.history.push({player:i,ai:move});}s.turn++;locked=false;if(s.turn===10){const result=S.lineResult(s.board);lineRender('10턴 완료');locked=true;done('라인 컨트롤',result.player,result.winner===1?'승리!':result.winner===2?'AI 승리':'무승부',true,['나 '+result.player+'점 : AI '+result.ai+'점','완성한 라인 '+S.lineWindows(s.board,1).length+'개 · 중앙 점수 '+S.centerScore(s.board,1)]);return}lineRender('AI가 '+(Math.floor(move/5)+1)+'행 '+(move%5+1)+'열에 착수했습니다.')};
})();